/**
 * Generates the small, statically-indexable story file for every LPM in the
 * React SDK registry. The shared implementation lives in storyFactory.tsx.
 *
 * Storybook requires each story title to be a literal in a source file, so a
 * single runtime loop cannot register all of these stories reliably.
 */

const fs = require("node:fs");
const path = require("node:path");
const ts = require("typescript");

const GENERATED_HEADER =
  "// This file is auto-generated by scripts/generate-lpm-stories.cjs";
const STORIES_DIR = path.resolve(__dirname, "../src/stories/lpm");
const REGISTRY_PATH = path.resolve(
  __dirname,
  "../../../react-paypal-js/src/v6/config/lpmRegistry.ts",
);
const CHECK_ONLY = process.argv.includes("--check");

// The registry has no runtime dependencies; transpiling it lets this Node 20
// script use the actual source of truth without adding a TS runner dependency.
require.extensions[".ts"] = (module, filename) => {
  const source = fs.readFileSync(filename, "utf8");
  const output = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2022,
    },
    fileName: filename,
  }).outputText;
  module._compile(output, filename);
};

const { LPM_REGISTRY } = require(REGISTRY_PATH);

function toPascalCase(key) {
  return key.charAt(0).toUpperCase() + key.slice(1);
}

function storyFileName(key) {
  return `${toPascalCase(key)}OneTimePaymentButton.stories.tsx`;
}

function storySource(key, displayName) {
  return `${GENERATED_HEADER}
// Run \`npm run generate:lpm-stories\` after changing LPM_REGISTRY.
import type { Meta } from "@storybook/react";
import {
  createLPMMetaExtras,
  createLPMStories,
  type LPMStoryArgs,
} from "../../shared/lpm/storyFactory";

const meta: Meta<LPMStoryArgs> = {
  title: "V6/Local Payment Methods/${displayName}",
  ...createLPMMetaExtras("${key}"),
};

export default meta;

export const Default = createLPMStories("${key}").Default;
`;
}

function main() {
  fs.mkdirSync(STORIES_DIR, { recursive: true });

  const expectedFiles = new Set();
  const changes = [];

  for (const [key, config] of Object.entries(LPM_REGISTRY)) {
    const fileName = storyFileName(key);
    const filePath = path.join(STORIES_DIR, fileName);
    const expected = storySource(key, config.displayName);
    const actual = fs.existsSync(filePath)
      ? fs.readFileSync(filePath, "utf8")
      : null;

    expectedFiles.add(fileName);
    if (actual === expected) {
      continue;
    }

    changes.push(
      actual === null ? `missing ${fileName}` : `outdated ${fileName}`,
    );
    if (!CHECK_ONLY) {
      fs.writeFileSync(filePath, expected);
    }
  }

  for (const fileName of fs.readdirSync(STORIES_DIR)) {
    if (!fileName.endsWith(".stories.tsx") || expectedFiles.has(fileName)) {
      continue;
    }

    const filePath = path.join(STORIES_DIR, fileName);
    const source = fs.readFileSync(filePath, "utf8");
    if (!source.startsWith(GENERATED_HEADER)) {
      continue;
    }

    changes.push(`unexpected ${fileName}`);
    if (!CHECK_ONLY) {
      fs.rmSync(filePath);
    }
  }

  if (changes.length === 0) {
    console.log("All LPM stories are up to date.");
    return;
  }

  if (CHECK_ONLY) {
    console.error(changes.join("\n"));
    process.exitCode = 1;
    return;
  }

  console.log(`Updated ${changes.length} LPM story files.`);
}

main();
